import { getCurrentLocale, localizeTime, deLocalizeTime, isValidTime, translate } from '@ps-refarch-ux/mfe-utils';
export function validateIsTime(input, condition, context) {
    const result = {
        isValid: isValidTime(input)
    };
    if (result.isValid) {
        context.parsedTime = deLocalizeTime(input);
    }
    else {
        result.errorMessage = translate(getCurrentLocale().DATETIME_FORMATS.shortTime === 'HH:mm' ? 'neon|validation engine|Must be a time (HH:MM)' : 'neon|validation engine|Must be a time (HH:MM AM or PM)');
    }
    return result;
}
export function validateMaxTime(input, maxTime, context) {
    const result = {
        isValid: context.parsedTime.getHours() * 60 + context.parsedTime.getMinutes() <= maxTime.getHours() * 60 + maxTime.getMinutes()
    };
    if (!result.isValid) {
        result.errorMessage = translate('neon|validation engine|The time must be on or before xx', { maxTime: localizeTime(maxTime) });
    }
    return result;
}
export function validateMinTime(input, minTime, context) {
    const result = {
        isValid: context.parsedTime.getHours() * 60 + context.parsedTime.getMinutes() >= minTime.getHours() * 60 + minTime.getMinutes()
    };
    if (!result.isValid) {
        result.errorMessage = translate('neon|validation engine|The time must be on or after xx', { minTime: localizeTime(minTime) });
    }
    return result;
}
